const koName = `${swaps.map((v) => `{{#if {{not_equal::${VAR}::${v}}}}}`).join('')}${ko('none')}${'{{/if}}'.repeat(swaps.length)}${swaps.map((v) => `{{#if {{equal::${VAR}::${v}}}}}${ko(v)}{{/if}}`).join('')}`;
const title = rec.title || `${orgNameCbs(dir, org)} (${koName})`;

